/**
 * The services' own marks, for telling them apart at a glance: SoundCloud's cloud and YouTube
 * Music's ring, drawn from Simple Icons (simpleicons.org, CC0); Yandex Music's burst in a circle,
 * traced from Icons8's line icon. All in one colour, so that they tint like any other icon.
 */
object ServiceIcons {
    val SoundCloud: ImageVector by lazy { icon("SoundCloud", SOUNDCLOUD) }
    val YouTubeMusic: ImageVector by lazy { icon("YouTube Music", YOUTUBE_MUSIC) }
    // Outlines with their holes (the ring, the burst's middle), filled even-odd.
    val YandexMusic: ImageVector by lazy { icon("Яндекс Музыка", YANDEX_MUSIC, PathFillType.EvenOdd) }

    private fun icon(name: String, path: String, fillType: PathFillType = PathFillType.NonZero): ImageVector =
        ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 24f,
            viewportHeight = 24f
        ).addPath(pathData = addPathNodes(path), pathFillType = fillType, fill = SolidColor(Color.Black)).build()

